        },
        {
          "certificate": {
            "l1_radius": "1",
            "euclidean_radius_squared": "1",
            "interval_before": "-1",
            "interval_after": "1",
            "null_envelope": "1/4",
            "cone_order_preserved": true
          },
          "derivation": "Null envelope fixture: t=1,x=(1,0) with C_a=1/4,mu_a=1, exactly matched physical speed c=1. L1 radius = |1|+|0|=1. Euclidean radius squared = 1^2+0^2=1. Interval before = -t = -1. Interval after = t = 1. Null envelope = 1/4 from C_a parameter. Cone order preserved: (1,0) lies on the light cone boundary."
        }
      ]
    }
  ],
  "summary": {
    "narrowest_defensible_thesis": "Causal refinement bounds are envelope-relative; they do not derive the Minkowski metric or its scale from causal order alone. The null envelope C_a provides a scale but not a metric signature.",
    "evidence_scope": "Derived from explicit counterexample fixtures and null envelope evaluation under stated parameterizations. Not a general theorem.",
    "next_concrete_test": "Vary a*v_hop(a) convergence rate relative to c and test whether cone_order_preserved holds outside the forward light cone for non-isotropic velocity profiles."
  },
  "requested_lifts": [
    {
      "id": "EXACT_RATIONAL",
      "reason": "To compute exact rational envelope values without floating-point approximation, especially for the null envelope C_a=1/4 and bound evaluations at rational coordinates."
    },
    {
      "id": "REFINEMENT_HYPOTHESES",
      "reason": "To formally track how the LR bound proposal improves or is refuted under convergence rate variation of a*v_hop(a) to c."
    }
  ],
  "learning": [
    {
      "kind": "rule",
      "text": "The LR bound min(1,C_a exp[-mu_a (||x||_1-a*v_hop(a)*t)/a]) is envelope-relative; it does not by itself establish causal order or metric signature. Cone order must be verified separately against the chosen metric."
    },
    "failure_or_gain": "gain",
    "pattern": "When a*v_hop(a) converges to c at different rates, the bound's exponential argument sign flips, causing the LR bound to cross from inside to outside the light cone. This does not refute causality but indicates the bound is not cone-relative."
    },
